      {id:35, type:"mcq", q:`What should you NOT put on a burn?`, opts:[`A. Cling film`, `B. Cool water`, `C. A clean plastic bag`, `D. Butter`], answer:`D`, explanation:`Do not apply butter, toothpaste, or oil — they trap heat and increase infection risk.`},
      {id:36, type:"fill", q:`Do not remove an object that is _____ in a wound`, answer:`embedded`, explanation:`Do not remove any object that is embedded; apply pressure around it instead.`},
      {id:37, type:"mcq", q:`At what rate should you give chest compressions during CPR?`, opts:[`A. 60-80 per minute`, `B. 100-120 per minute`, `C. 140-160 per minute`, `D. 80-100 per minute`], answer:`B`, explanation:`Push at a rate of 100 to 120 compressions per minute.`},
      {id:38, type:"fill", q:`During CPR, give 30 compressions then _____ rescue breaths`, answer:`2`, acceptedAnswers:[`two`], explanation:`Do 30 compressions, then 2 rescue breaths.`},
      {id:39, type:"fill", q:`The song used to keep the compression beat is '_____ Alive'`, answer:`Stayin'`, acceptedAnswers:[`Staying`, `Stayin`], explanation:`The beat matches 'Stayin' Alive' by the Bee Gees.`},
      {id:40, type:"mcq", q:`Without bystander CPR, the survival rate for out-of-hospital cardiac arrest is:`, opts:[`A. Less than 10%`, `B. About 25%`, `C. About 50%`, `D. Less than 1%`], answer:`A`, explanation:`It's less than 10% without bystander CPR, but can triple with immediate action.`}
