// ── Consumers read from LISTENING_BANK only (single source) ──────────────────
// Practice page: all sections, flat.
export function getPracticeSections(): BankListeningSection[] {
  return LISTENING_BANK;
}

// Full mock: slot-mix one random Part 1 + Part 2 + Part 3 + Part 4 (real exam order),
// shaped to the ListeningTest interface the mock's ListeningSection expects.
export function getMockListeningTest() {
  const pick = (part: number) => {
    const pool = LISTENING_BANK.filter(s => s.part === part);
    return pool[Math.floor(Math.random() * pool.length)];
  };
  const chosen = [pick(1), pick(2), pick(3), pick(4)];
  let n = 0;
  return {
    id: "mock-" + chosen.map(s => s.id).join("_"),
    sections: chosen.map((s, i) => ({
      sectionNumber: i + 1,
      title: `Section ${i + 1}`,
      context: s.context,
      instructions: "Answer the questions as you listen. The recording plays once.",
      audio: s.audio,
      // renumber 1..40 across the assembled test
      questions: s.questions.map(q => ({
        id: ++n,
        type: q.type,
        q: q.q,
        opts: q.opts,
        answer: q.answer,
      })),
    })),
  };
}
